     1|/**
     2| * Canonical login state machine.
     3| *
     4| * Enforces a single deterministic state transition graph for the login screen.
     5| * Prevents duplicate taps, concurrent login attempts, and invalid transitions.
     6| *
     7| * States:
     8| *   IDLE → VALIDATING → AUTHENTICATING → AUTHORIZING → PERSISTING → NAVIGATING → SUCCESS
     9| *   Any state → FAILED (recoverable) → IDLE
    10| *   Any state → ERROR (terminal) → IDLE (after ack)
    11| *
    12| * No secrets are logged. Only state names and transition metadata.
    13| */
    14|
    15|export type LoginState =
    16|  | 'IDLE'
    17|  | 'VALIDATING'
    18|  | 'AUTHENTICATING'
    19|  | 'AUTHORIZING'
    20|  | 'PERSISTING'
    21|  | 'NAVIGATING'
    22|  | 'SUCCESS'
    23|  | 'FAILED'
    24|  | 'ERROR';
    25|
    26|export interface LoginStateTransition {
    27|  from: LoginState;
    28|  to: LoginState;
    29|  timestamp: number;
    30|  reason?: string;
    31|}
    32|
    33|/**
    34| * Valid state transitions. Any transition not in this map is rejected.
    35| */
    36|const VALID_TRANSITIONS: ReadonlySet<string> = new Set([
    37|  'IDLE->VALIDATING',
    38|  'VALIDATING->AUTHENTICATING',
    39|  'VALIDATING->FAILED',
    40|  'AUTHENTICATING->AUTHORIZING',
    41|  'AUTHENTICATING->FAILED',
    42|  'AUTHENTICATING->SUCCESS',
    43|  'AUTHORIZING->PERSISTING',
    44|  'AUTHORIZING->FAILED',
    45|  'AUTHORIZING->SUCCESS',
    46|  'PERSISTING->NAVIGATING',
    47|  'PERSISTING->FAILED',
    48|  'NAVIGATING->SUCCESS',
    49|  'NAVIGATING->FAILED',
    50|  'FAILED->IDLE',
    51|  'ERROR->IDLE',
    52|  // Allow short-circuit from AUTHENTICATING -> SUCCESS for non-owner flows
    53|  // that don't need a separate authorization stage.
    54|  'IDLE->FAILED',
    55|  'SUCCESS->IDLE',
    56|]);
    57|
    58|export class LoginStateMachine {
    59|  private currentState: LoginState = 'IDLE';
    60|  private transitionLog: LoginStateTransition[] = [];
    61|  private inFlight: boolean = false;
    62|  private lastTransitionTime: number = 0;
    63|
    64|  get state(): LoginState {
    65|    return this.currentState;
    66|  }
    67|
    68|  get isInFlight(): boolean {
    69|    return this.inFlight;
    70|  }
    71|
    72|  get transitions(): readonly LoginStateTransition[] {
    73|    return this.transitionLog;
    74|  }
    75|
    76|  /**
    77|   * Attempt a state transition. Returns true if the transition was accepted.
    78|   * Rejects if the transition is invalid or if a login is already in flight
    79|   * (unless transitioning to FAILED/ERROR/IDLE).
    80|   */
    81|  transition(to: LoginState, reason?: string): boolean {
    82|    const from = this.currentState;
    83|    const key = `${from}->${to}`;
    84|
    85|    if (!VALID_TRANSITIONS.has(key)) {
    86|      console.log(`[LoginStateMachine] Rejected invalid transition ${key}`);
    87|      return false;
    88|    }
    89|
    90|    const now = Date.now();
    91|    this.currentState = to;
    92|    this.lastTransitionTime = now;
    93|    this.inFlight = to !== 'IDLE' && to !== 'SUCCESS' && to !== 'FAILED' && to !== 'ERROR';
    94|    this.transitionLog.push({ from, to, timestamp: now, reason });
    95|
    96|    // Keep log bounded.
    97|    if (this.transitionLog.length > 50) {
    98|      this.transitionLog = this.transitionLog.slice(-50);
    99|    }
   100|
   101|    console.log(`[LoginStateMachine] ${from} -> ${to}${reason ? ` (${reason})` : ''}`);
   102|    return true;
   103|  }
   104|
   105|  /**
   106|   * Try to start a new login attempt. Returns false if a login is already
   107|   * in progress, preventing duplicate taps and concurrent submissions.
   108|   */
   109|  tryStart(): boolean {
   110|    if (this.inFlight || this.currentState !== 'IDLE') {
   111|      console.log(`[LoginStateMachine] Duplicate tap blocked: state=${this.currentState} inFlight=${this.inFlight}`);
   112|      return false;
   113|    }
   114|    return this.transition('VALIDATING', 'login attempt started');
   115|  }
   116|
   117|  /**
   118|   * Reset to IDLE after a failure or terminal error.
   119|   */
   120|  reset(): void {
   121|    this.inFlight = false;
   122|    this.currentState = 'IDLE';
   123|    console.log('[LoginStateMachine] Reset to IDLE');
   124|  }
   125|
   126|  /**
   127|   * Get the elapsed time since the last transition in milliseconds.
   128|   */
   129|  get elapsedSinceLastTransitionMs(): number {
   130|    return this.lastTransitionTime > 0 ? Date.now() - this.lastTransitionTime : 0;
   131|  }
   132|}
